    """列出全部课程概览，按课程编号升序，每项含编号、标题和章节数。"""
    rows = conn.execute(
        """
        SELECT c.id, c.title, COUNT(ch.course_id) AS chapter_count
        FROM courses AS c
        LEFT JOIN chapters AS ch ON ch.course_id = c.id
        GROUP BY c.id, c.title
        ORDER BY c.id
